mapper.select:
SELECT p.id, p.name, p.type, p.price, p.img, p.abv, p.order_count
FROM t_user_favorite f JOIN t_user u ON u.id = f.user_id JOIN t_product p ON p.id = f.product_id
WHERE u.id = #{userId} AND u.auth_epoch = #{authEpoch}
ORDER BY f.created_at DESC, f.product_id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM t_user_favorite f
JOIN t_user u ON u.id = f.user_id JOIN t_product p ON p.id = f.product_id
WHERE u.id = #{userId} AND u.auth_epoch = #{authEpoch}
